const COS = Math.cos(50.8 * Math.PI / 180);
const PX = lon => lon * COS * 100, PY = lat => -lat * 100;
const pathOf = rings => rings.map(r => 'M' + r.map(([x, y]) => `${PX(x).toFixed(2)} ${PY(y).toFixed(2)}`).join('L') + 'Z').join('');
const lineOf = l => 'M' + l.map(([x, y]) => `${PX(x).toFixed(2)} ${PY(y).toFixed(2)}`).join('L');
