const OVER_BORDER = GEO.over_border.map(lineOf).join('');
const REG_DDR = pathOf(GEO.reg['Thüringen']) + pathOf(GEO.reg['Sachsen']);
const REG_BORDER = GEO.reg_border.map(lineOf).join('');
