function routePath(cam, upto) {
  const pts = ROUTE.map(([lo, la]) => toScr(lo, la, cam));
  let d = `M ${pts[0][0]} ${pts[0][1]}`;
  for (let i = 1; i < pts.length - 1; i++) { const mx = (pts[i][0] + pts[i + 1][0]) / 2, my = (pts[i][1] + pts[i + 1][1]) / 2; d += ` Q ${pts[i][0]} ${pts[i][1]} ${mx} ${my}`; }
  d += ` L ${pts[pts.length - 1][0]} ${pts[pts.length - 1][1]}`;
  return `<path d="${d}" fill="none" stroke="#fff" stroke-width="16" stroke-linecap="round" pathLength="1" stroke-dasharray="${upto} 1"/><path d="${d}" fill="none" stroke="${K.ink}" stroke-width="7" stroke-linecap="round" pathLength="1" stroke-dasharray="${upto} 1"/>`;
}
function routePoint(cam, u) {
  // approximate point along the route polyline
  const pts = ROUTE.map(([lo, la]) => toScr(lo, la, cam));
  let L = 0; const seg = [];
  for (let i = 1; i < pts.length; i++) { const l = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); seg.push(l); L += l; }
  let d = cl(u) * L;
  for (let i = 0; i < seg.length; i++) { if (d <= seg[i]) { const f = seg[i] ? d / seg[i] : 0; return [lerp(pts[i][0], pts[i + 1][0], f), lerp(pts[i][1], pts[i + 1][1], f)]; } d -= seg[i]; }
  return pts[pts.length - 1];
}
