  const lt = t - t0;
  const fl = loop ? .6 + .4 * back(prog(lt, 1.2, 1.5)) : .55 + .45 * back(prog(lt, 0, .25)) - .2 * prog(lt, 2.4, 3) + .2 * back(prog(lt, 3.6, 3.8));
